alter table public.profiles add column if not exists avatar_url text;
alter table public.profiles add column if not exists bio text not null default '';
alter table public.profiles add column if not exists verse text not null default '';
alter table public.posts add column if not exists image_url text;
create table if not exists public.likes(post_id bigint not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.comments(id bigint generated by default as identity primary key,post_id bigint not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.prayers(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 1000),is_testimony boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.prayer_support(prayer_id bigint not null references public.prayers(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(prayer_id,user_id));
create table if not exists public.follows(follower_id uuid not null references public.profiles(id) on delete cascade,following_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists public.messages(id bigint generated by default as identity primary key,sender_id uuid not null references public.profiles(id) on delete cascade,receiver_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 1000),created_at timestamptz not null default now(),read_at timestamptz);
create table if not exists public.notifications(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete cascade,type text not null,text text not null,entity_id text,created_at timestamptz not null default now(),read_at timestamptz);
alter table public.likes enable row level security; alter table public.comments enable row level security; alter table public.prayers enable row level security; alter table public.prayer_support enable row level security; alter table public.follows enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security;
drop policy if exists likes_read on public.likes; create policy likes_read on public.likes for select to authenticated using(true);
drop policy if exists likes_insert_own on public.likes; create policy likes_insert_own on public.likes for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists likes_delete_own on public.likes; create policy likes_delete_own on public.likes for delete to authenticated using(auth.uid()=user_id);
drop policy if exists comments_read on public.comments; create policy comments_read on public.comments for select to authenticated using(true);
drop policy if exists comments_insert_own on public.comments; create policy comments_insert_own on public.comments for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists prayers_read on public.prayers; create policy prayers_read on public.prayers for select to authenticated using(true);
drop policy if exists prayers_insert_own on public.prayers; create policy prayers_insert_own on public.prayers for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists prayer_support_read on public.prayer_support; create policy prayer_support_read on public.prayer_support for select to authenticated using(true);
drop policy if exists prayer_support_insert_own on public.prayer_support; create policy prayer_support_insert_own on public.prayer_support for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists prayer_support_delete_own on public.prayer_support; create policy prayer_support_delete_own on public.prayer_support for delete to authenticated using(auth.uid()=user_id);
drop policy if exists follows_read on public.follows; create policy follows_read on public.follows for select to authenticated using(true);
drop policy if exists follows_insert_own on public.follows; create policy follows_insert_own on public.follows for insert to authenticated with check(auth.uid()=follower_id);
drop policy if exists follows_delete_own on public.follows; create policy follows_delete_own on public.follows for delete to authenticated using(auth.uid()=follower_id);
drop policy if exists messages_read_participant on public.messages; create policy messages_read_participant on public.messages for select to authenticated using(auth.uid()=sender_id or auth.uid()=receiver_id);
drop policy if exists messages_insert_sender on public.messages; create policy messages_insert_sender on public.messages for insert to authenticated with check(auth.uid()=sender_id);
drop policy if exists messages_update_receiver on public.messages; create policy messages_update_receiver on public.messages for update to authenticated using(auth.uid()=receiver_id) with check(auth.uid()=receiver_id);
drop policy if exists notifications_read_own on public.notifications; create policy notifications_read_own on public.notifications for select to authenticated using(auth.uid()=user_id);
drop policy if exists notifications_insert_authenticated on public.notifications; create policy notifications_insert_authenticated on public.notifications for insert to authenticated with check(auth.uid()=actor_id);
drop policy if exists notifications_update_own on public.notifications; create policy notifications_update_own on public.notifications for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public) values('avatars','avatars',true) on conflict(id) do update set public=true;
insert into storage.buckets(id,name,public) values('post-images','post-images',true) on conflict(id) do update set public=true;
drop policy if exists public_read_avatars on storage.objects; create policy public_read_avatars on storage.objects for select to public using(bucket_id='avatars');
drop policy if exists public_read_post_images on storage.objects; create policy public_read_post_images on storage.objects for select to public using(bucket_id='post-images');
drop policy if exists upload_own_avatar on storage.objects; create policy upload_own_avatar on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists upload_own_post_image on storage.objects; create policy upload_own_post_image on storage.objects for insert to authenticated with check(bucket_id='post-images' and (storage.foldername(name))[1]=auth.uid()::text);
